import { expect, test } from 'vitest';
import { page } from 'vitest/browser';
import { renderFileList } from './file-list.js';

test('deletes the selected files', async () => {
  renderFileList(document.body, ['a.txt', 'b.txt', 'c.txt']);
  await page.getByLabelText('a.txt').click();
  await page.getByLabelText('b.txt').click();
  await page.getByRole('button', { name: 'Delete', exact: false }).click();
  await expect.element(page.getByText('c.txt')).toBeInTheDocument();
  expect(page.getByRole('listitem').elements()).toHaveLength(1);
});

